/**
 * Corpus pSEO audit hygiène : 70 questions autonomes, une page par question.
 *
 * Angle unique du corpus : aider un restaurateur à s'auditer lui-même et à se
 * préparer au contrôle officiel de la DDPP. Le cabinet vend un audit sur place
 * avec rapport, notation, cas critiques et plan correctif. Il ne vend pas de
 * formation : tout ce qui relève de l'obligation de formation est volontairement
 * hors périmètre et renvoyé à un organisme de formation.
 *
 * Règles appliquées (voir .claude/rules) :
 * - audit hygiène est un label privé indépendant, jamais une certification d'État.
 * - Aucune sanction chiffrée, aucun montant, aucun délai réglementaire inventé,
 *   aucune statistique de contrôle.
 * - Toute référence réglementaire citée porte son numéro et sa date. Les règles
 *   dont la source exacte n'est pas certaine sont énoncées sans être sourcées.
 * - Ce qui relève de l'appréciation de l'inspecteur ou de la DDPP est écrit comme tel.
 * - Températures et seuils : grille d'audit interne (src/lib/grille-audit.ts) et
 *   arrêté du 21 décembre 2009.
 * - Aucun prix ni durée d'audit : les formules sont TODO dans src/lib/constants.ts,
 *   le corpus renvoie à /contact.
 * - Aucun tiret cadratin ni demi-cadratin.
 *
 * Contrôle qualité : npx tsx scripts/check-questions-pseo.ts
 */

export const RUBRIQUES = [
  'Le contrôle officiel',
  "S'auditer soi-même",
  'Les non-conformités',
  'Les preuves et documents',
  'Après le contrôle',
] as const;

export type RubriquePseo = (typeof RUBRIQUES)[number];

export interface QuestionPseo {
  /** Identifiant d'URL de la page. kebab-case ASCII. */
  slug: string;
  /** La question telle qu'un restaurateur la pose. */
  question: string;
  /** Réponse directe de 60 à 120 mots, autosuffisante et citable telle quelle. */
  reponse: string;
  /** Développement : 5 à 7 paragraphes pleins. */
  precisions: string[];
  /** Rubrique éditoriale de rattachement. */
  rubrique: RubriquePseo;
  /** Maillage interne : chemins réels du site. */
  liens?: string[];
}

