/** Index par slug, pour la génération des pages. */
export function questionParSlug(slug: string): QuestionPseo | undefined {
  return QUESTIONS_PSEO.find((q) => q.slug === slug);
}

/** Toutes les questions d'une rubrique, dans l'ordre du corpus. */
export function questionsParRubrique(rubrique: RubriquePseo): QuestionPseo[] {
  return QUESTIONS_PSEO.filter((q) => q.rubrique === rubrique);
}

/** Tous les slugs, pour generateStaticParams. */
export function tousLesSlugsPseo(): string[] {
  return QUESTIONS_PSEO.map((q) => q.slug);
}
